CREATE OR REPLACE FUNCTION public.neutral_offer_text(_text text,_org uuid) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s text:=coalesce(_text,''); v text; BEGIN
FOR v IN SELECT name FROM organizations WHERE id=_org UNION SELECT full_name FROM profiles WHERE organization_id=_org UNION SELECT email FROM profiles WHERE organization_id=_org UNION SELECT phone FROM profiles WHERE organization_id=_org UNION SELECT email FROM organizations WHERE id=_org UNION SELECT phone FROM organizations WHERE id=_org LOOP IF length(trim(coalesce(v,'')))>2 THEN s:=regexp_replace(s,regexp_replace(v,'([.\\+*?\[\](){}^$|])','\\\1','g'),'','gi'); END IF; END LOOP;
s:=regexp_replace(s,'https?://[^\s]+|www\.[^\s]+|[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}|\+?[0-9][0-9 () .-]{7,}[0-9]','','gi');
s:=regexp_replace(s,'[^\n]*(Habitoo|agen[tț]ie|agen[tț]ia|agent |telefon|contact|whatsapp|facebook|instagram|comision)[^\n]*','','gi');
s:=regexp_replace(s,'(strada|str\.|bulevardul|bd\.|șoseaua|soseaua|intrarea|aleea|adresa)[^,;.\n]*','','gi');
s:=regexp_replace(s,'[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}','','gi');
IF s ~* '^Sector(ul)? [1-6]$|^Bucure[șşs]ti Sector(ul)? [1-6]$' THEN s:='București'; END IF; RETURN trim(s); END $$;
REVOKE ALL ON FUNCTION public.neutral_offer_text(text,uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.guard_collaborator_delivery() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN
IF NEW.agent_id<>auth.uid() OR NEW.organization_id<>public.current_org() OR NOT EXISTS(SELECT 1 FROM neutral_offer_links l JOIN properties p ON p.id=l.property_id WHERE l.id=NEW.link_id AND l.property_id=NEW.property_id AND l.organization_id=NEW.organization_id AND p.organization_id=public.current_org() AND p.deleted_at IS NULL) THEN RAISE EXCEPTION 'Oferta indisponibila'; END IF;
IF TG_OP='INSERT' THEN IF NOT EXISTS(SELECT 1 FROM neutral_offer_links l JOIN properties p ON p.id=l.property_id WHERE l.id=NEW.link_id AND l.revoked_at IS NULL AND p.status='active') THEN RAISE EXCEPTION 'Oferta indisponibila'; END IF; IF NEW.recipient_agent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.collaborator_offer_recipients() r WHERE r.user_id=NEW.recipient_agent_id) THEN RAISE EXCEPTION 'Colaborator indisponibil'; END IF;
ELSIF ROW(NEW.id,NEW.organization_id,NEW.agent_id,NEW.property_id,NEW.link_id,NEW.recipient_agent_id,NEW.recipient,NEW.recipient_name,NEW.channel) IS DISTINCT FROM ROW(OLD.id,OLD.organization_id,OLD.agent_id,OLD.property_id,OLD.link_id,OLD.recipient_agent_id,OLD.recipient,OLD.recipient_name,OLD.channel) THEN RAISE EXCEPTION 'Destinatarul nu poate fi modificat'; END IF; RETURN NEW; END $$;